<?php
declare(strict_types=1);
require __DIR__ . '/config.php';require __DIR__ . '/helpers.php';$profile=business_profile($pdo);$credits=credit_orders($pdo);$total=0.0;foreach($credits as $c)$total+=(float)$c['current_total'];$paidCredits=$pdo->query("SELECT o.id,o.credit_name,o.total,o.credit_paid_at,o.payment_method,t.table_no FROM orders o JOIN cafe_tables t ON t.id=o.table_id WHERE o.status='paid' AND o.credit_name IS NOT NULL ORDER BY o.credit_paid_at DESC LIMIT 20")->fetchAll();
?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veresiyeler • <?= e($profile['name']) ?></title><?php if($profile['logo_path']!==''):?><link rel="icon" href="<?= e($profile['logo_path']) ?>"><?php endif;?><link rel="stylesheet" href="assets/style.css?v=10.1"></head><body><header class="topbar"><div class="container topbar-inner"><a class="brand" href="home.php"><?php if($profile['logo_path']!==''):?><span class="brand-mark brand-mark-image"><img src="<?= e($profile['logo_path']) ?>" alt="Logo"></span><?php else:?><span class="brand-mark"><?= e(business_initials($profile['name'])) ?></span><?php endif;?><span><?= e($profile['name']) ?><small>Veresiye Takibi</small></span></a><div class="nav-actions"><a class="btn btn-ghost" href="home.php">← Ana Ekran</a><a class="btn btn-ghost" href="orders.php">Adisyonlar</a><a class="btn" href="admin/login.php">Admin</a></div></div></header><main class="standalone-page container"><section class="admin-heading"><div><div class="eyebrow">Açık Hesaplar</div><h1 class="admin-title">Veresiyeler</h1><p class="muted">Veresiye adisyonlarına sonradan ürün ekleyebilir, kalemleri değiştirebilir ve ödeme alındığında kapatabilirsiniz.</p></div><div class="finance-card credit-highlight mini-finance"><span>Toplam alacak</span><strong><?= money($total) ?></strong><small><?= count($credits) ?> açık veresiye</small></div></section><?php if(!$credits):?><section class="panel"><div class="empty-receipt"><strong>Açık veresiye yok</strong><br><span>Masa adisyonundan “Veresiye Yaz” ile kayıt oluşturabilirsiniz.</span></div></section><?php else:?><section class="credit-grid"><?php foreach($credits as $c):$dt=$c['credit_created_at']?:$c['opened_at'];?><a class="credit-card" href="credit.php?id=<?= (int)$c['id'] ?>"><div class="credit-card-head"><span class="badge">#<?= (int)$c['id'] ?></span><span class="credit-age"><?= e(relative_time_tr($dt)) ?></span></div><h2><?= e((string)($c['credit_name']?:'İsimsiz Veresiye')) ?></h2><p><?= e((string)($c['credit_note']??'')) ?></p><div class="credit-meta"><span>İlk masa: <?= (int)$c['table_no'] ?></span><span><?= e(date('d.m.Y H:i',strtotime($dt))) ?></span></div><div class="credit-total"><span><?= (int)$c['item_count'] ?> ürün</span><strong><?= money((float)$c['current_total']) ?></strong></div></a><?php endforeach;?></section><?php endif;?>
<section class="panel paid-credit-panel"><div class="panel-title"><div><div class="eyebrow">Ödendi</div><h2>Son kapanan veresiyeler</h2></div><span class="badge success"><?= count($paidCredits) ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Adisyon</th><th>Kişi</th><th>Tutar</th><th>Ödeme</th><th>Ödendiği tarih</th></tr></thead><tbody><?php if(!$paidCredits):?><tr><td colspan="5" class="muted">Henüz ödenmiş veresiye yok.</td></tr><?php endif;?><?php foreach($paidCredits as $p):$label=['cash'=>'Nakit','card'=>'Kart','other'=>'Diğer'][$p['payment_method']??'other']??'Diğer';?><tr><td>#<?= (int)$p['id'] ?></td><td><strong><?= e((string)$p['credit_name']) ?></strong></td><td><?= money((float)$p['total']) ?></td><td><?= e($label) ?></td><td><?= $p['credit_paid_at']?e(date('d.m.Y H:i',strtotime($p['credit_paid_at']))):'—' ?></td></tr><?php endforeach;?></tbody></table></div></section>
</main><script src="assets/app.js?v=10"></script></body></html>
